def merge_intervals(iv: list) -> list:
    if not iv:
        return []
    iv.sort()
    merged = [iv[0]]
    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)
    return merged

def median(nums: list) -> float:
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return float(nums_sorted[mid])

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f'{current_char}{count}')
            current_char = char
            count = 1
    result.append(f'{current_char}{count}')
    return ''.join(result)

def chunk(xs: list, k: int) -> list:
    result = []
    for i in range(0, len(xs), k):
        result.append(xs[i:i+k])
    return result

def camel_to_snake(s: str) -> str:
    result = []
    for i, c in enumerate(s):
        if c.isupper() and (i == 0 or not s[i-1].islower() or s[i-1].isnumeric()):
            result.append('_')
        result.append(c.lower())
    return ''.join(result)

def parse_price(s: str) -> float:
    import re
    match = re.search(r'\$(\d{1,3}(?:,\d{3})*\.\d{2})', s)
    if not match:
        return 0.0
    price_str = match.group(1).replace(',', '')
    return float(price_str)

def c_to_f(c: float) -> float:
    f = c * 9/5 + 32
    return round(f, 1)

def roman_to_int(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)
    return not stack

def is_palindrome(s: str) -> bool:
    s = ''.join(char.lower() for char in s if char.isalnum())
    return s == s[::-1]

def flatten(xs: list) -> list:
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

